/**
 * Fails if `lib/build-info.ts` does not name the commit that is actually deployed.
 *
 * FREE: no call, no STT/TTS, no LLM. Reads git and one HTTP response.
 *
 * Why this exists
 * ---------------
 * `components/build-stamp.tsx` exists so a stale deploy is VISIBLE instead of argued
 * about — the shell used to carry a hardcoded date, which is how several deploys went
 * unnoticed. That only works if the stamp is true.
 *
 * The stamp is generated by `scripts/write-build-info.mjs` from `git rev-parse HEAD`, and
 * it is written into `lib/build-info.ts` as a committed file. The documented deploy was
 * `npx opennextjs-cloudflare build && npx wrangler deploy`, which does **not** go through
 * `npm run build` and so never regenerated it. A deploy that way shipped a stamp reading
 * `ed07534` while the running code was two commits newer — the exact failure the stamp
 * exists to catch, produced by the stamp itself.
 *
 * The offset is inherent and is NOT a bug: the stamp is generated during the build, and
 * committing the generated file is necessarily a *later* commit than the one it names.
 * So the live stamp is expected to be the commit immediately before the one carrying
 * `lib/build-info.ts`. This check accepts that, and rejects anything else.
 *
 *   node scripts/check-build-stamp.mjs                 # against the live site
 *   SITE=http://localhost:8787 node scripts/check-build-stamp.mjs
 */
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

const site = process.env.SITE || "https://legal-voice-agent.adribmahmud.workers.dev";

const git = (...args) => {
  try {
    return execFileSync("git", args, { encoding: "utf8" }).trim();
  } catch {
    return "";
  }
};

const results = [];
const check = (label, ok, extra = "") => {
  results.push(ok);
  console.log(`${ok ? "PASS" : "FAIL"} ${label}${extra ? " :: " + extra : ""}`);
};

const stamped = /BUILD_SHA = "([^"]+)"/.exec(readFileSync(resolve("lib/build-info.ts"), "utf8"))?.[1] ?? "";
const head = git("rev-parse", "--short", "HEAD");
const parent = git("rev-parse", "--short", "HEAD~1");

check("build-info.ts carries a SHA", Boolean(stamped), stamped || "(empty)");

// The stamped SHA must be a real ancestor, and within one commit of HEAD.
const known = [head, parent].filter(Boolean);
check("the stamped SHA is HEAD or its parent", known.includes(stamped), `stamped=${stamped} head=${head} parent=${parent}`);

check("build-info.ts is committed with the change it names",
  Boolean(git("log", "-1", "--format=%H", "--", "lib/build-info.ts")) &&
  !git("status", "--porcelain", "--", "lib/build-info.ts"),
  git("status", "--porcelain", "--", "lib/build-info.ts") || "clean");

// Now the live site, read the way a person reads it: the rendered footer.
//
// Reading `BUILD_SHA` out of a client chunk does not work — the constant is inlined and
// minified, so a chunk scan finds nothing and the check silently SKIPs its most important
// assertion. The stamp is rendered by `DlaoShell`, so the page is authenticated; the
// one-click staff login is what the other console suites use.
let live = "(unread)";
try {
  const { chromium } = await import("playwright-core");
  const browser = await chromium.launch();
  const page = await (await browser.newContext()).newPage();
  await page.goto(site, { waitUntil: "networkidle" });
  await page.evaluate(async () => {
    await fetch("/api/portal/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      credentials: "include",
      body: JSON.stringify({ role: "dlao" }),
    });
  });
  await page.goto(`${site}/dlao`, { waitUntil: "networkidle" });
  await page.waitForTimeout(1500);
  const text = await page.evaluate(() => {
    const el = [...document.querySelectorAll("span")].find((e) => /বিল্ড/.test(e.textContent || ""));
    return el ? (el.textContent || "").replace(/\s+/g, " ").trim() : null;
  });
  await browser.close();
  live = text?.match(/বিল্ড:\s*([0-9a-f]{6,40})/)?.[1] ?? "(not rendered)";
} catch (err) {
  check("the live stamp is readable", false, String(err).slice(0, 90));
}

check("the live stamp is readable", live !== "(unread)" && live !== "(not rendered)", live);
if (/^[0-9a-f]{6,40}$/.test(live)) {
  check("the deployed site stamps the current build", live === stamped || live === head,
    `live=${live} stamped=${stamped} head=${head}`);
}

const failed = results.filter((r) => !r).length;
console.log(`\n${results.length - failed}/${results.length} checks passed`);
if (failed) process.exit(1);
